param([Parameter(Mandatory=$true)][string]$PublicDeviceUrl,[Parameter(Mandatory=$true)][string]$CaCertificatePath,[switch]$ResolveToLoopback)
$ErrorActionPreference="Stop";Set-StrictMode -Version Latest;if(-not(Test-Path $CaCertificatePath)){throw "CA certificate not found"};$u=[Uri]$PublicDeviceUrl;if($u.Scheme-ne"https"){throw "HTTPS required"};$curl=(Get-Command curl.exe -ErrorAction Stop).Source;$a=@("--silent","--show-error","--fail","--cacert",$CaCertificatePath);if($ResolveToLoopback){$p=if($u.Port-gt0){$u.Port}else{443};$a+=@("--resolve",("{0}:{1}:127.0.0.1" -f $u.Host,$p))};$a+=($PublicDeviceUrl.TrimEnd("/")+"/health");$b=&$curl @a;if($LASTEXITCODE-ne0){throw "direct reachability failed"};$h=$b|ConvertFrom-Json;if($h.status-ne"ok"-or$h.role-ne"device-ingress"){throw "unexpected health response"};[pscustomobject]@{reachable=$true;endpoint=$PublicDeviceUrl;role=$h.role}|ConvertTo-Json